    'im.plain': '{n} dos {total} projetos que o Pulse segue usam o {lib}. {active} deles tiveram trabalho nos últimos 30 dias.', 'im.plain.1': 'Um dos {total} projetos que o Pulse segue usa o {lib}.', 'im.unlisted': 'Poucos projetos constroem hoje sobre {lib}, por isso já não está na lista acima. O histórico fica aqui.', 'im.none': 'Nenhum dos projetos que o Pulse segue usa o {lib} ainda, até onde os ficheiros públicos mostram.',
